 FrameworkElement QuickFormatLabel(string extension){var row=new DockPanel();var arrow=BuilderSvgIcon("quick-chevron",11,mutedBrush);arrow.VerticalAlignment=VerticalAlignment.Center;DockPanel.SetDock(arrow,Dock.Right);row.Children.Add(arrow);var text=Text("."+extension,12.5,ink);text.FontWeight=FontWeights.SemiBold;row.Children.Add(text);return row;}
 async void RunQuickFileTool(){
  if(quickToolBusy||!File.Exists(quickFileInput))return;string source=quickFileInput,category=QuickFileCategory(source),mode=quickMode;double strength=quickCompression;string extension=mode=="convert"?quickFileFormat:category=="image"?"jpg":category=="audio"?"mp3":category=="video"?"mp4":"zip";string output;
