 void RenderQuickFileDone(StackPanel card){var check=new Border{Width=44,Height=44,CornerRadius=new CornerRadius(22),Background=QuickTint(.16),Child=BuilderSvgIcon("quick-check",20,accentBrush),HorizontalAlignment=HorizontalAlignment.Center,Margin=new Thickness(0,6,0,14)};card.Children.Add(check);var title=Text(Path.GetFileName(quickFileOutput),14.5,ink);title.FontWeight=FontWeights.SemiBold;title.HorizontalAlignment=HorizontalAlignment.Center;card.Children.Add(title);long original=new FileInfo(quickFileInput).Length,final=new FileInfo(quickFileOutput).Length;string detail=quickMode=="compress"?QuickBytes(original)+" → "+QuickBytes(final)+(final<original?" · "+Math.Round((1-final/(double)Math.Max(1,original))*100)+"% smaller":" · no size reduction"):"Saved as ."+Path.GetExtension(quickFileOutput).TrimStart('.')+" · "+QuickBytes(final);var sub=Text(detail,12,mutedBrush);sub.HorizontalAlignment=HorizontalAlignment.Center;sub.Margin=new Thickness(0,4,0,18);card.Children.Add(sub);var actions=new Grid();actions.ColumnDefinitions.Add(new ColumnDefinition());actions.ColumnDefinitions.Add(new ColumnDefinition());var show=QuickButton("Show in folder",()=>Process.Start(new ProcessStartInfo("explorer.exe","/select,\""+quickFileOutput+"\""){UseShellExecute=true}),10);show.Margin=new Thickness(0,0,4,0);actions.Children.Add(show);var again=QuickButton("Process another file",()=>{quickFileInput="";quickFileOutput="";RenderQuickSearch();},10);again.Margin=new Thickness(4,0,0,0);Grid.SetColumn(again,1);actions.Children.Add(again);card.Children.Add(actions);}
 static void ProcessQuickFile(string input,string output,string extension,bool compress,double strength,string runtime){
  if(String.Equals(Path.GetFullPath(input),Path.GetFullPath(output),StringComparison.OrdinalIgnoreCase))throw new IOException("The output must be different from the original file.");
  string temp=Path.Combine(Path.GetDirectoryName(output),".awl-"+Guid.NewGuid().ToString("N")+"."+extension);try{
   string category=QuickFileCategory(input);
   if(extension=="zip"){using(var zip=ZipFile.Open(temp,ZipArchiveMode.Create))zip.CreateEntryFromFile(input,Path.GetFileName(input),compress&&strength<30?CompressionLevel.Fastest:CompressionLevel.Optimal);}
   else if(category=="image")WriteQuickImage(input,temp,extension,compress?Math.Max(10,100-strength):92);
   else if(category=="text")WriteQuickDocument(input,temp,extension);
   else if(category=="audio"||category=="video")WriteQuickMedia(input,temp,extension,compress,strength,runtime);
   else throw new InvalidOperationException("This file can be packaged as ZIP; no compatible conversion is available.");
   if(!File.Exists(temp)||new FileInfo(temp).Length==0)throw new IOException("No output was produced.");if(File.Exists(output))File.Replace(temp,output,null);else File.Move(temp,output);
  }finally{if(File.Exists(temp))File.Delete(temp);}
 }
 static void WriteQuickImage(string input,string output,string extension,double quality){using(var image=System.Drawing.Image.FromFile(input)){if(extension=="jpg"){using(var bitmap=new System.Drawing.Bitmap(image.Width,image.Height)){using(var g=System.Drawing.Graphics.FromImage(bitmap)){g.Clear(System.Drawing.Color.White);g.DrawImage(image,0,0,image.Width,image.Height);}var codec=System.Drawing.Imaging.ImageCodecInfo.GetImageEncoders().First(x=>x.MimeType=="image/jpeg");using(var parameters=new System.Drawing.Imaging.EncoderParameters(1)){parameters.Param[0]=new System.Drawing.Imaging.EncoderParameter(System.Drawing.Imaging.Encoder.Quality,(long)quality);bitmap.Save(output,codec,parameters);}}}else image.Save(output,extension=="png"?System.Drawing.Imaging.ImageFormat.Png:extension=="gif"?System.Drawing.Imaging.ImageFormat.Gif:extension=="bmp"?System.Drawing.Imaging.ImageFormat.Bmp:System.Drawing.Imaging.ImageFormat.Tiff);}}
 static void WriteQuickDocument(string input,string output,string extension){string text;if(Path.GetExtension(input).Equals(".docx",StringComparison.OrdinalIgnoreCase)){using(var zip=ZipFile.OpenRead(input)){var entry=zip.GetEntry("word/document.xml");if(entry==null)throw new InvalidDataException("The document has no Word text content.");var xml=new XmlDocument{XmlResolver=null};using(var stream=entry.Open())using(var reader=XmlReader.Create(stream,new XmlReaderSettings{DtdProcessing=DtdProcessing.Prohibit,XmlResolver=null}))xml.Load(reader);var ns=new XmlNamespaceManager(xml.NameTable);ns.AddNamespace("w","http://schemas.openxmlformats.org/wordprocessingml/2006/main");text=String.Join(Environment.NewLine,xml.SelectNodes("//w:p",ns).Cast<XmlNode>().Select(p=>String.Concat(p.SelectNodes(".//w:t|.//w:tab|.//w:br",ns).Cast<XmlNode>().Select(n=>n.LocalName=="tab"?"\t":n.LocalName=="br"?Environment.NewLine:n.InnerText))));}}else text=File.ReadAllText(input);
  if(extension=="txt"){File.WriteAllText(output,text,new UTF8Encoding(false));return;}
  using(var zip=ZipFile.Open(output,ZipArchiveMode.Create)){WriteQuickZipText(zip,"[Content_Types].xml","<Types xmlns=\"http://schemas.openxmlformats.org/package/2006/content-types\"><Default Extension=\"rels\" ContentType=\"application/vnd.openxmlformats-package.relationships+xml\"/><Default Extension=\"xml\" ContentType=\"application/xml\"/><Override PartName=\"/word/document.xml\" ContentType=\"application/vnd.openxmlformats-officedocument.wordprocessingml.document.main+xml\"/></Types>");WriteQuickZipText(zip,"_rels/.rels","<Relationships xmlns=\"http://schemas.openxmlformats.org/package/2006/relationships\"><Relationship Id=\"rId1\" Type=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument\" Target=\"word/document.xml\"/></Relationships>");using(var writer=XmlWriter.Create(zip.CreateEntry("word/document.xml").Open(),new XmlWriterSettings{Encoding=new UTF8Encoding(false),CloseOutput=true})){writer.WriteStartElement("w","document","http://schemas.openxmlformats.org/wordprocessingml/2006/main");writer.WriteStartElement("w","body",null);foreach(string line in text.Replace("\r\n","\n").Split('\n')){writer.WriteStartElement("w","p",null);writer.WriteStartElement("w","r",null);writer.WriteStartElement("w","t",null);writer.WriteAttributeString("xml","space",null,"preserve");writer.WriteString(line);writer.WriteEndElement();writer.WriteEndElement();writer.WriteEndElement();}writer.WriteEndElement();writer.WriteEndElement();}}}
 static void WriteQuickZipText(ZipArchive zip,string name,string text){using(var writer=new StreamWriter(zip.CreateEntry(name).Open(),new UTF8Encoding(false)))writer.Write(text);}
 static void WriteQuickMedia(string input,string output,string extension,bool compress,double strength,string runtime){
  if(String.IsNullOrEmpty(runtime)||!File.Exists(runtime))throw new InvalidOperationException("The media conversion runtime is unavailable.");string category=QuickFileCategory(input),arguments="-hide_banner -y -i \""+input+"\" ";
  if(category=="audio"){arguments+="-vn -c:a "+(extension=="mp3"?"libmp3lame":extension=="wav"?"pcm_s16le":extension=="flac"?"flac":"aac");if(extension=="mp3"||extension=="m4a")arguments+=" -b:a "+(compress?(int)(256-strength*2):192)+"k";}
  else{int bitrate=6000;if(compress){double seconds=QuickMediaDuration(input,runtime);double total=new FileInfo(input).Length*8/Math.Max(1,seconds)/1000;bitrate=(int)Math.Max(32,Math.Min(6000,total*(1-strength/110)-80));}arguments+="-map 0:v:0 -map 0:a:0? -vf \"scale=trunc(iw/2)*2:trunc(ih/2)*2\" -c:v libopenh264 -rc_mode bitrate -b:v "+bitrate+"k -maxrate "+bitrate+"k -bufsize "+(bitrate*2)+"k -c:a "+(extension=="avi"?"libmp3lame":"aac")+" -b:a "+(compress?80:128)+"k";if(extension=="mp4"||extension=="mov")arguments+=" -movflags +faststart";}
  arguments+=" -threads 2 \""+output+"\"";using(var p=Process.Start(new ProcessStartInfo(runtime,arguments){UseShellExecute=false,CreateNoWindow=true,RedirectStandardError=true})){string error=p.StandardError.ReadToEnd();p.WaitForExit();if(p.ExitCode!=0)throw new InvalidOperationException("Media conversion failed: "+String.Join(" ",error.Split(new[]{'\r','\n'},StringSplitOptions.RemoveEmptyEntries).Reverse().Take(3).Reverse()));}
 }
 static double QuickMediaDuration(string input,string runtime){using(var p=Process.Start(new ProcessStartInfo(runtime,"-hide_banner -i \""+input+"\""){UseShellExecute=false,CreateNoWindow=true,RedirectStandardError=true})){string info=p.StandardError.ReadToEnd();p.WaitForExit();var m=System.Text.RegularExpressions.Regex.Match(info,@"Duration:\s*(\d+):(\d+):([\d.]+)");if(!m.Success)throw new InvalidDataException("The media duration could not be determined.");return Int32.Parse(m.Groups[1].Value)*3600+Int32.Parse(m.Groups[2].Value)*60+Double.Parse(m.Groups[3].Value,CultureInfo.InvariantCulture);}}
